private let earthOrder = ["戊","己","庚","辛","壬","癸","丁","丙","乙"], circle = [3,8,1,6,5,0,7,2], stars = ["天蓬星","天芮星","天冲星","天辅星","天禽星","天心星","天柱星","天任星","天英星"], doors = ["休门","死门","伤门","杜门","","开门","惊门","生门","景门"], deities = ["值符","螣蛇","太阴","六合","白虎","玄武","九地","九天"]
